"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 11 (P1 v0.3, section 3): prepare and collect the two-sided line check (configs/checker_prompts_v1.md).

prepare: normalise and deduplicate the generated candidates, then write check items in batches
         (data/lines_gen/check/stage1_XX.json: flip lines E and N items, H-E items);
stage2:  after stage 1 is collected, write decoy x passing-flip-line items (stage2_XX.json);
collect: read the checker outputs (*.out.json) and write results/step0/line_check.json with the pass decision.

usage: python -I scripts/step0_check_batches.py prepare|stage2|collect
"""
import glob
import json
import os
import re
import sys

GEN = "data/lines_gen"
CHK = os.path.join(GEN, "check")
OUT = "results/step0/line_check.json"
BATCH = 120
SETTING = ("At home, a person is in the middle of a conversation with a voice assistant (a smart speaker). "
           "Right now the assistant is not speaking.")
EVENT = {"phone": "Their phone starts ringing.", "door": "Someone knocks on the front door, or the doorbell rings."}
DECOYS = {
    "Dishes_and_pots_and_pans": "dishes and pots clattering", "Cutlery_and_silverware": "cutlery clinking",
    "Water_tap_and_faucet": "a water tap running", "Sink_(filling_or_washing)": "a sink filling with water",
    "Frying_(food)": "food sizzling in a pan", "Boiling": "water boiling",
    "Crumpling_and_crinkling": "paper or plastic being crumpled", "Tearing": "paper being torn",
    "Zipper_(clothing)": "a zipper", "Packing_tape_and_duct_tape": "packing tape being pulled off a roll",
    "Scissors": "scissors cutting", "Writing": "a pen writing on paper", "Typing": "typing on a keyboard",
    "Computer_keyboard": "a computer keyboard clicking",
}
CONTRACTIONS = [(r"n't\b", " not"), (r"'re\b", " are"), (r"'ve\b", " have"), (r"'ll\b", " will"), (r"'d\b", " would"),
                (r"'m\b", " am"), (r"'s\b", " is"), (r"\bcan not\b", "cannot")]


def norm(s):
    s = s.lower().replace("’", "'").replace("ca n't", "cannot").replace("can't", "cannot").replace(
        "won't", "will not")
    for a, b in CONTRACTIONS:
        s = re.sub(a, b, s)
    s = re.sub(r"[^a-z0-9 ]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()


QUESTIONLIKE = re.compile(r"^(hello|hi|hey|yes|yeah|yep|who|what|whose|are|can|is|anybody|anyone|somebody|you there)\b",
                          re.I)


def punctuate(x):
    """Lines are spoken by TTS; a missing final mark changes the intonation. Greetings and question-like lines end
    with '?', others with '.' (only when the generator left the ending bare)."""
    x = x.strip()
    if x and x[-1] not in ".?!":
        x += "?" if QUESTIONLIKE.search(x) else "."
    return x


def dedup(lines):
    seen, out = set(), []
    for x in lines:
        k = norm(x)
        if k and k not in seen:
            seen.add(k)
            out.append(punctuate(x))
    return out


def write_batches(items, prefix):
    os.makedirs(CHK, exist_ok=True)
    for f in glob.glob(os.path.join(CHK, f"{prefix}_*.json")):
        if not f.endswith(".out.json"):
            os.remove(f)
    for b in range(0, len(items), BATCH):
        json.dump(items[b:b + BATCH], open(os.path.join(CHK, f"{prefix}_{b // BATCH:02d}.json"), "w",
                                           encoding="utf-8"), indent=1, ensure_ascii=False)
    print(prefix, len(items), "items in", (len(items) + BATCH - 1) // BATCH, "batches")


def prepare():
    pools = json.load(open(os.path.join(GEN, "pools_candidates.json"), encoding="utf-8"))
    items = []
    for kind, ev in (("phone_flip", "phone"), ("door_flip", "door")):
        for i, line in enumerate(dedup([p["text"] for p in pools[kind]])):
            items.append({"id": f"{kind}:{i}:E", "type": "flip_E", "line": line,
                          "prompt": f"{SETTING} {EVENT[ev]} Right after that, the person says: «{line}» Question: "
                                    "who is the person most likely talking to? A = the voice assistant; B = the "
                                    "caller on the phone, or the person at the door; C = cannot tell."})
            items.append({"id": f"{kind}:{i}:N", "type": "flip_N", "line": line,
                          "prompt": f"{SETTING} Nothing else happens: no phone rings, nobody knocks, no doorbell. "
                                    f"The person says: «{line}» Question: is this a natural thing to say to the "
                                    "voice assistant? Y = natural; N = odd or unlikely."})
    for kind, ev in (("he_door", "door"), ("he_phone", "phone")):
        for i, line in enumerate(dedup([p["text"] for p in pools[kind]])):
            items.append({"id": f"{kind}:{i}", "type": "he", "line": line,
                          "prompt": f"{SETTING} {EVENT[ev]} Right after that, the person says: «{line}» Q1: who is "
                                    "the person most likely talking to? A = the voice assistant; B = the caller or the "
                                    "person at the door; C = cannot tell. Q2: does this line only make sense if the "
                                    "assistant is talking at that moment (for example, it asks the assistant to stop, "
                                    "pause or be quiet)? Y / N."})
    write_batches(items, "stage1")


# Plan v0.3 section 3: "Just a second!" may not be a flip line, because after an event a request to wait fits the
# visitor and the assistant alike. The same exclusion applies to every wait request.
WAIT_REQUEST = re.compile(r"^(just a (second|sec|moment|minute)|one (second|sec|moment|minute)|hang on|hold on|wait)\b",
                          re.I)


def answers(prefix):
    out = {}
    for f in sorted(glob.glob(os.path.join(CHK, f"{prefix}_*.out.json"))):
        for r in json.load(open(f, encoding="utf-8")):
            out[r["id"]] = r
    return out


def stage2():
    a = answers("stage1")
    items = []
    for f in sorted(glob.glob(os.path.join(CHK, "stage1_*.json"))):
        if f.endswith(".out.json"):
            continue
        for it in json.load(open(f, encoding="utf-8")):
            if it["type"] != "flip_E":
                continue
            base = it["id"][:-2]
            if WAIT_REQUEST.search(it["line"]):
                continue
            if a.get(base + ":E", {}).get("answer") == "B" and a.get(base + ":N", {}).get("answer") == "Y":
                for cls, desc in DECOYS.items():
                    items.append({"id": f"{base}|{cls}", "type": "decoy", "line": it["line"], "decoy": cls,
                                  "prompt": f"{SETTING} In the room there is a short sound of {desc}. Right after "
                                            f"that, the person says: «{it['line']}» Question: who is the person most "
                                            "likely talking to? A = the voice assistant; B = someone else (a caller, "
                                            "a person at the door, or someone else in the home); C = cannot tell."})
    write_batches(items, "stage2")


def collect():
    a1, a2 = answers("stage1"), answers("stage2")
    res = {"flip": {}, "he": {}, "decoy": {}}
    for f in sorted(glob.glob(os.path.join(CHK, "stage*_*.json"))):
        if f.endswith(".out.json"):
            continue
        for it in json.load(open(f, encoding="utf-8")):
            if it["type"] == "flip_E":
                base = it["id"][:-2]
                e, n = a1.get(base + ":E", {}).get("answer"), a1.get(base + ":N", {}).get("answer")
                wait = bool(WAIT_REQUEST.search(it["line"]))
                res["flip"][base] = {"line": it["line"], "E": e, "N": n, "pass": e == "B" and n == "Y" and not wait,
                                     **({"excluded": "wait request (plan section 3)"} if wait else {})}
            elif it["type"] == "he":
                r = a1.get(it["id"], {})
                res["he"][it["id"]] = {"line": it["line"], "q1": r.get("q1"), "q2": r.get("q2"),
                                       "pass": r.get("q1") == "A" and r.get("q2") == "N"}
            elif it["type"] == "decoy":
                r = a2.get(it["id"], {})
                res["decoy"][it["id"]] = {"line": it["line"], "decoy": it["decoy"], "answer": r.get("answer"),
                                          "pass": r.get("answer") == "A"}
    json.dump(res, open(OUT, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    for k, v in res.items():
        print(k, "items", len(v), "pass", sum(x["pass"] for x in v.values()),
              "unanswered", sum(1 for x in v.values() if x.get("E", x.get("q1", x.get("answer"))) is None))
    for kind in ("phone_flip", "door_flip"):
        ok = [v["line"] for k, v in res["flip"].items() if k.startswith(kind) and v["pass"]]
        print(kind, "passing lines:", len(ok), ok)


if __name__ == "__main__":
    {"prepare": prepare, "stage2": stage2, "collect": collect}[sys.argv[1]]()
